<template>
    <div class="design-panel user-select-none">
        <div class="display-flex">
            <my-icon style="min-width: 20px; height: 20px" @click="clickAuxiliaryLineVisible"
                 class="cursor-pointer iconfont "
                 :class="[auxiliaryLineVisible? 'icon-yanjing_xianshi_o' :'icon-yanjing_yincang_o']" />
            <rule :direction="highlightRule.horizontal.direction"
                  :length="panel.width"
                  :auxiliaryLineVisible="auxiliaryLineVisible"
                  :highlight="highlightRule.horizontal.highlight"
                  :scroll="highlightRule.horizontal.scroll" />
        </div>
        <div class="display-flex design-content_inner"
             tabindex="0">
            <rule :direction="highlightRule.vertical.direction"
                  :length="panel.height"
                  :auxiliaryLineVisible="auxiliaryLineVisible"
                  :highlight="highlightRule.vertical.highlight"
                  :scroll="highlightRule.vertical.scroll" />
            <div class="affix-container design-content-scroll " @scroll="scroll" @wheel="wheel"
                 @contextmenu.prevent="showBatchMoveMenu"
                 ref="designScrollRef">
                <div class="design-content design-content-bg"
                     ref="designContentRef"
                     :style="{transformOrigin: 'left top',
                          transform: 'scale('+scaleUtil.miniMap.scale+')',
                            minWidth: valueUnit(panel.width),
                            width: valueUnit(panel.width),
                            height: valueUnit(panel.height),
                           }"
                     :class="{'dropInIs': panel.runtimeOption.dragInIs}">
                    <design v-if="panel.pageHeader != undefined" :element="panel.pageHeader" />
                    <design v-if="panel.pageFooter != undefined" :element="panel.pageFooter" />
                    <element-list :elementList="panel.elementList" />
                </div>
            </div>

            <div v-if="batchMoveMenu.visible" class="design-context-menu-mask" @click="closeBatchMoveMenu">
                <div class="design-context-menu"
                     :style="{ left: batchMoveMenu.x + 'px', top: batchMoveMenu.y + 'px' }"
                     @click.stop>
                    <button type="button"
                            @click="moveSelectedElementsTo('pageHeader')">
                        {{ i18n('handle.moveToPageHeader') }}
                    </button>
                    <button type="button"
                            @click="moveSelectedElementsTo('pageFooter')">
                        {{ i18n('handle.moveToPageFooter') }}
                    </button>
                </div>
            </div>

            <auxiliary-line :element="item" :key="item.id"
                            :scroll-x="highlightRule.horizontal.scroll"
                            :scroll-y="highlightRule.vertical.scroll"
                            v-for="(item) in panel.auxiliaryLineList" />
            
            <template v-if="auxiliaryLineVisible">
                <auxiliary-line tmp :element="appStore.auxiliaryLineTmp" v-if="appStore.auxiliaryLineTmp.x != null" />
            </template>
        </div>
    </div>

</template>

<script setup lang="ts">
import Rule from '@myprint/design/components/my/rule/rule.vue';
import { scaleUtil } from '@myprint/design/utils/scaleUtil';
import { nextTick, onMounted, onUnmounted, reactive, ref } from 'vue-demi';
import { Container, ContentScaleVo, ElementOption, MyElement } from '@myprint/design/types/entity';
import { ActionEnum, record, Snapshot } from '@myprint/design/utils/historyUtil';
import { addElement, getCurrentPanel, handle, initElement, installParentElement, none, removeElement, valueUnit } from '@myprint/design/utils/elementUtil';
import { unit2px } from '@myprint/design/utils/devicePixelRatio';
import { useAppStoreHook as useAppStore } from '@myprint/design/stores/app';
import ElementList from '@myprint/design/components/design/element-list.vue';
import { mountedKeyboardEvent, unMountedKeyboardEvent } from '@myprint/design/utils/keyboardUtil';
import { changeDragSnapIs, initMoveable, updatePanel } from '@myprint/design/plugins/moveable/moveable';
import Design from '@myprint/design/components/design/design.vue';
import { initSelecto, selecto } from '@myprint/design/plugins/moveable/selecto';
import AuxiliaryLine from '@myprint/design/components/design/auxiliary/auxiliary-line.vue';
import MyIcon from '@myprint/design/components/my/icon/my-icon.vue';
import { i18n } from '@myprint/design/locales';
import { generateUUID, mitt } from '@myprint/design/utils/utils';

const panel = getCurrentPanel();
const designContentRef = ref<InstanceType<any>>();
const appStore = useAppStore();
const contentScale = reactive({
    openIs: false
} as ContentScaleVo);
const auxiliaryLineVisible = ref(true);
const batchMoveMenu = reactive({
    visible: false,
    x: 0,
    y: 0
});
let resizeObserver: ResizeObserver;
const highlightRule = reactive({
    horizontal: {
        direction: 'horizontal',
        highlight: { x: undefined! as number, width: 0 } as Container,
        scroll: 0
    },
    vertical: {
        direction: 'vertical',
        highlight: { x: undefined! as number, width: 0 } as Container,
        scroll: 0
    }
});

const designScrollRef = ref<HTMLElement>()!;
// 事件绑定
mitt.on('elementClick', elementClick);
mitt.on('scaleEvent', scaleEvent);
mitt.on('panelSnapshot', panelSnapshot);
mitt.on('updatePanel', updatePanel);
mitt.on('triggerScroll', updatePanel);
mitt.on('scaleMove', scaleMove);

onMounted(() => {
    // 挂载键盘事件
    mountedKeyboardEvent();
    nextTick(() => {
        initSelecto();
        initMoveable(selecto.value, highlightRule);
    });
    mitt.emit('minimapViewportSize', {
        width: designScrollRef.value!.clientWidth,
        height: designScrollRef.value!.clientHeight
    } as Container);
    // console.log(designScrollRef.value!.clientWidth)
    // 创建 ResizeObserver 实例
    resizeObserver = new ResizeObserver((_entries) => {
        // entries 是 ResizeObserverEntry 对象的数组
        mitt.emit('minimapViewportSize', {
            width: designScrollRef.value!.clientWidth,
            height: designScrollRef.value!.clientHeight
        } as Container);
    });
    resizeObserver.observe(designScrollRef.value!);
    
    const rect = designScrollRef.value!.getBoundingClientRect();
    panel.runtimeOption.target = designContentRef.value
    appStore.panelPosition = { x: rect.x, y: rect.y, scrollX: 0, scrollY: 0 };
});
onUnmounted(() => {
    resizeObserver.disconnect();
    unMountedKeyboardEvent();
});

function clickAuxiliaryLineVisible() {
    auxiliaryLineVisible.value = !auxiliaryLineVisible.value;
    for (let myAuxiliaryLine of panel.auxiliaryLineList) {
        myAuxiliaryLine.runtimeOption.auxiliaryLineStatus = auxiliaryLineVisible.value ? 'SHOW' : 'HIDDEN';
    }
    changeDragSnapIs();
}

/**
 * 滑动事件
 */
function scroll(_scrollData: any) {
    highlightRule.horizontal.scroll = designScrollRef.value!.scrollLeft;
    highlightRule.vertical.scroll = designScrollRef.value!.scrollTop;
    mitt.emit('minimapViewportScroll', {
        x: designScrollRef.value!.scrollLeft,
        y: designScrollRef.value!.scrollTop
    } as Container);
    
    appStore.panelPosition.scrollX = designScrollRef.value!.scrollLeft;
    appStore.panelPosition.scrollY = designScrollRef.value!.scrollTop;
}

function wheel(event: any) {
    event.preventDefault(); // 阻止默认滚动行为
    
    // 更新滚动位置
    designScrollRef.value!.scrollTop += event.deltaY;
    designScrollRef.value!.scrollLeft += event.deltaX;
    
    mitt.emit('minimapViewportScroll', {
        x: designScrollRef.value!.scrollLeft,
        y: designScrollRef.value!.scrollTop
    } as Container);
    
    appStore.panelPosition.scrollX = designScrollRef.value!.scrollLeft;
    appStore.panelPosition.scrollY = designScrollRef.value!.scrollTop;
}

/**
 * minimap 的 移动事件
 */
function scaleMove(data: any) {
    // console.log('move', data.x, data.y)
    designScrollRef.value!.scrollTo(data.x, data.y);
}

function panelSnapshot(snapshot: Snapshot) {
    // console.log(123)
    // console.log(action)
    if (!snapshot.type) {
        snapshot.type = 'PANEL';
    }
    record(snapshot);
}

function elementClick(element: MyElement) {
    // console.log('elementClick')
    // console.log('鼠标点击', element)
    contentScale.openIs = true;
    none(panel.pageHeader);
    none(panel.pageFooter);
    elementListNone();
    handle(element);
}


function scaleEvent() {
    //let mmDiv = document.createElement('div');
    //通过更改 className 来触发重绘
    designContentRef.value?.classList.add('design-content-scale');
    nextTick(() => {
        setTimeout(() => {
            designContentRef.value?.classList.remove('design-content-scale');
        }, 100);
        // scrollbarRef.value.update()
    });
}

function elementListNone() {
    for (let valueElement of panel.elementList!) {
        none(valueElement);
    }
}

function getSelectedPanelElements() {
    return appStore.currentElement.filter(element =>
        element.runtimeOption.parent === panel
        && element.type != 'PageHeader'
        && element.type != 'PageFooter'
    );
}

function showBatchMoveMenu(event: MouseEvent) {
    const selectedElements = getSelectedPanelElements();

    // 页眉/页脚容器不存在时菜单仍显示，移入时自动创建（存量模板大多没拖过页眉页脚）
    if (selectedElements.length < 2) {
        return;
    }

    batchMoveMenu.visible = true;
    batchMoveMenu.x = event.clientX;
    batchMoveMenu.y = event.clientY;
}

function closeBatchMoveMenu() {
    batchMoveMenu.visible = false;
}

// 模板未带页眉/页脚时按工具箱拖入的同样默认值自动创建（fixed=true 每页重复），
// 几何与挂载方式与 base-widget.vue 的拖入路径保持一致
function ensureBatchMoveTarget(key: 'pageHeader' | 'pageFooter'): MyElement {
    const existing = panel[key] as unknown as MyElement | undefined;
    if (existing != null) {
        return existing;
    }
    const container = {
        id: generateUUID(),
        type: key,
        option: { fixed: true } as ElementOption,
        height: 30
    } as unknown as MyElement;
    initElement(panel, container, 0);
    container.width = panel.width;
    container.x = 0;
    container.y = key == 'pageHeader' ? 0 : panel.height - container.height;
    container.runtimeOption.width = unit2px(panel.width);
    container.runtimeOption.x = 0;
    container.runtimeOption.y = unit2px(container.y);
    panel[key] = container as any;
    installParentElement(panel, container);
    return container;
}

function moveSelectedElementsTo(key: 'pageHeader' | 'pageFooter') {
    const target = ensureBatchMoveTarget(key);
    const selectedElements = getSelectedPanelElements();

    batchMoveMenu.visible = false;
    if (selectedElements.length < 2) {
        return;
    }

    for (let element of selectedElements) {
        delete element.option.fixed;
        delete element.option.displayStrategy;
        removeElement(element);
        element.x -= target.x;
        element.y -= target.y;
        // 批量移入时元素可能来自正文任意位置，相对坐标为负或越界，钳制在容器内
        element.x = Math.min(Math.max(element.x, 0), Math.max(target.width - element.width, 0));
        element.y = Math.min(Math.max(element.y, 0), Math.max(target.height - element.height, 0));
        addElement(panel, target, element);
    }

    updatePanel();
    record({
        type: 'PANEL',
        action: ActionEnum.BATCH_MOVE,
        elementList: selectedElements
    });
}
</script>
